WITH cleaned AS (SELECT id, device, browser, started_at, country, CONCAT(country, ' ', browser) AS country_browser, YEAR(started_at) AS started_at_year, COALESCE(browser, 'NONE') AS browser_filled FROM sessions WHERE started_at > TIMESTAMP '2023-07-18 20:00:00') SELECT DATE_TRUNC('QUARTER', started_at) AS quarter_start, CASE WHEN started_at_year >= 80 THEN 'LARGE' ELSE 'SMALL' END AS started_at_year_tier, DATE_TRUNC('YEAR', started_at) AS year_start, MAX(started_at) AS last_started_at, (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 AS span_minutes, COUNT(*) FILTER (WHERE device = 'tablet') AS tablet_rows, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', started_at) ORDER BY (UNIX_TIMESTAMP(MAX(started_at)) - UNIX_TIMESTAMP(MIN(started_at))) / 60 DESC) AS span_minutes_dense_rank FROM cleaned GROUP BY DATE_TRUNC('QUARTER', started_at), CASE WHEN started_at_year >= 80 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('YEAR', started_at) ORDER BY year_start DESC;
